#include "game.hpp"
#include "json.hpp"
#include <filesystem>
#include <fstream>
#include <iostream>
#include <stdexcept>
using namespace hyperion;
namespace {
int checks=0;void check(bool v,const char* why){++checks;if(!v)throw std::runtime_error(why);}bool near(double a,double b){return std::abs(a-b)<1e-6;}
nlohmann::json snapshot(const State& s){auto p=std::filesystem::temp_directory_path()/"hyperion-fieldwork-test.json";std::string e;check(saveState(s,p.string(),e),"Snapshot saves");std::ifstream in(p);nlohmann::json j;in>>j;in.close();std::filesystem::remove(p);return j;}
void deploy(Game& g){g.system("HOME");g.s.selectedPlanet=2;check(g.descend(),"Deploy field fixture");g.storeShipStock({});g.s.battery=50;g.s.economy.missions.clear();g.s.economy.contracts.clear();g.s.economy.routes.clear();g.s.flight.traffic.clear();for(auto& site:g.s.economy.settlements)site.owner=1;}
Contact find(Game& g,const std::string& kind){auto p=g.activePlanet();auto origin=g.s.surface;int cx=int(std::floor(origin.x/86)),cy=int(std::floor(origin.y/86));for(int x=cx-6;x<=cx+6;x++)for(int y=cy-6;y<=cy+6;y++)for(const auto& c:g.universe.surfaceObjects(p,x,y))if(c.kind==kind){g.s.surface=g.s.waypoint=c.pos;g.registerExpeditionHabitat();return c;}throw std::runtime_error("Generated fixture missing "+kind);}
void clearRare(Game& g){auto p=g.activePlanet();int cx=int(g.s.surface.x/86),cy=int(g.s.surface.y/86);for(int x=cx-9;x<=cx+9;x++)for(int y=cy-9;y<=cy+9;y++)for(const auto& c:g.universe.surfaceObjects(p,x,y))if(c.kind=="signal"||c.kind=="relic")g.s.scanned.insert(c.id);}
}
int main(){try{
 for(const char* seed:{"MERIDIAN-0001","GLASS-002","DEEP-BLUE"}){
  Game g(seed);deploy(g);auto mineral=find(g,"mineral");auto before=snapshot(g.s);auto study=g.fieldQuote("fieldStudy",mineral.id);check(study.available&&study.gain[Research]>0,"Focused study quotes actual data");for(int i=0;i<30;i++){g.fieldQuote("fieldStudy",mineral.id);g.fieldQuote("fieldCollect",mineral.id);g.fieldSites();}check(snapshot(g.s)==before,"All field quotes and opportunity queries are read-only");
  double hour=g.s.hours,battery=g.s.battery;g.issueOrder("fieldStudy",mineral.id);check(near(g.s.hours,hour+1)&&near(g.s.battery,battery-2)&&g.s.resources[3]==study.gain[Research],"Study costs one hour and six battery before normal recovery");check(g.s.economy.hold[Ore]==0&&g.s.resources[1]==0,"Non-invasive study does not automatically mine the cache");auto collect=g.fieldQuote("fieldCollect",mineral.id);check(collect.available&&collect.gain[Ore]+collect.gain[Crystal]>0,"Studied mineral exposes a finite collection choice");auto cargo=g.shipStock();g.issueOrder("fieldCollect",mineral.id);check(near(g.shipStock()[Ore]-cargo[Ore],collect.gain[Ore])&&near(g.shipStock()[Crystal]-cargo[Crystal],collect.gain[Crystal]),"Collection matches its quoted real cargo");before=snapshot(g.s);g.issueOrder("fieldCollect",mineral.id);check(snapshot(g.s)==before,"An exhausted cache cannot be collected twice");
  auto path=std::filesystem::temp_directory_path()/"hyperion-field-roundtrip.json";std::string error;check(saveState(g.s,path.string(),error),"Save collection marker");Game loaded(seed);if(!loadState(loaded.s,path.string(),error))throw std::runtime_error("Load collection marker / "+error);++checks;loaded.universe.reset(loaded.s.seed,loaded.s.generation,loaded.s.legacySystems);check(!loaded.fieldQuote("fieldCollect",mineral.id).available,"Reload cannot replenish finite material allowance");std::filesystem::remove(path);
  Game legacy(seed);deploy(legacy);auto old=find(legacy,"mineral");legacy.catalogue(old);check(!legacy.fieldQuote("fieldCollect",old.id).available,"Legacy standard scans cannot yield a second material payout");
  Game life(seed);deploy(life);auto c=find(life,"flora");auto* h=contactHabitat(life.s.economy,life.universe,life.activePlanet(),c);check(h!=nullptr,"Habitat is registered");double sampled=h->sampled;life.issueOrder("fieldStudy",c.id);h=contactHabitat(life.s.economy,life.universe,life.activePlanet(),c);check(h->sampled==sampled&&life.s.resources[2]==0,"Study leaves population sampling budgets intact");auto sample=life.fieldQuote("fieldCollect",c.id);check(sample.available,"Viable population supports conservative sampling");double biomass=life.shipStock()[Biomass];life.issueOrder("fieldCollect",c.id);h=contactHabitat(life.s.economy,life.universe,life.activePlanet(),c);check(near(h->sampled-sampled,sample.gain[Biomass])&&near(life.shipStock()[Biomass]-biomass,sample.gain[Biomass]),"Samples debit actual living biomass into the shared hold");
  Game depleted(seed);deploy(depleted);c=find(depleted,"flora");depleted.issueOrder("fieldStudy",c.id);auto& habitat=ensureContactHabitat(depleted.s.economy,depleted.universe,depleted.activePlanet(),c);for(auto& population:habitat.populations)population.mass=population.capacity*.2;before=snapshot(depleted.s);check(!depleted.fieldQuote("fieldCollect",c.id).available,"Sampling respects depleted population reserves");depleted.issueOrder("fieldCollect",c.id);check(snapshot(depleted.s)==before,"Rejected sampling cannot alter time, cargo or populations");
 }
 Game move;deploy(move);clearRare(move);move.s.waypoint={move.s.surface.x+110,move.s.surface.y};move.s.battery=30;auto push=move.fieldQuote("fieldPush");check(push.available&&push.wear>0&&push.move.turns==3,"Push exposes its speed, effort and wear tradeoff");double hp=move.s.hull,hour=move.s.hours;move.issueOrder("fieldPush");check(near(move.s.surface.x,push.move.position.x)&&near(move.s.surface.y,push.move.position.y)&&near(move.s.hull,hp-push.wear)&&near(move.s.battery,26)&&near(move.s.hours,hour+1),"Push commits exactly the previewed endpoint and costs");
 Stock supplies{};supplies[Alloy]=4;supplies[Components]=2;move.storeShipStock(supplies);move.s.hull=93;move.s.battery=30;auto repair=move.fieldQuote("fieldRepair");check(repair.available&&repair.repair==7,"Repair quotes only missing hull");move.issueOrder("fieldRepair");check(move.s.hull==100&&move.shipStock()[Alloy]==2&&move.shipStock()[Components]==1&&move.s.battery==26,"Field repair spends finite alloy, components and battery");auto frozen=snapshot(move.s);move.issueOrder("fieldRepair");check(snapshot(move.s)==frozen,"Sound hull repair is a free rejection");
 Game route;deploy(route);clearRare(route);auto origin=route.s.surface;route.s.waypoint={origin.x+43,origin.y};hour=route.s.hours;auto reports=route.recentTurns.size();route.issueOrder("fieldTravel");check(near(route.s.surface.x,origin.x+43)&&near(route.s.hours,hour+2)&&!route.planMove().valid,"Route following reaches the exact waypoint without repeated commands");check(route.recentTurns.size()==reports+1&&route.lastTurn.hours==2&&route.lastTurn.requested==2,"Multi-step route has one complete resolution report");route.s.waypoint={route.s.surface.x+250,route.s.surface.y};hour=route.s.hours;route.issueOrder("fieldTravel");check(near(route.s.hours,hour+6)&&route.planMove().valid,"Automatic travel is bounded to six turns and keeps the remaining route");
 Game deadline;deploy(deadline);clearRare(deadline);deadline.s.waypoint={deadline.s.surface.x+110,deadline.s.surface.y};Contract c;c.id="FIELD-DEADLINE";c.settlement=deadline.s.economy.settlements.front().id;c.accepted=true;c.deadline=deadline.s.hours+2.5;deadline.s.economy.contracts.push_back(c);hour=deadline.s.hours;deadline.issueOrder("fieldTravel");check(near(deadline.s.hours,hour+2)&&deadline.planMove().valid&&!deadline.lastTurn.interruption.empty(),"Route pauses before an imminent deadline and preserves the choice");
 Game ocean;deploy(ocean);check(ocean.dive(),"Ocean fixture deploys");ocean.s.oceanTargetX=ocean.s.oceanX+38;ocean.s.targetDepth=ocean.s.depth;auto p=ocean.fieldQuote("fieldPush");check(p.available,"Ocean push supports horizontal survey travel");ocean.issueOrder("fieldPush");check(near(ocean.s.oceanX,p.move.position.x)&&near(ocean.s.depth,p.move.depth),"Ocean push uses the same certified preview as movement");ocean.s.depth=ocean.maxDepth()+10;frozen=snapshot(ocean.s);ocean.issueOrder("fieldTravel");check(snapshot(ocean.s)==frozen,"Automatic travel cannot silently resolve unsafe pressure exposure");
 Game invalid;auto before=snapshot(invalid.s);for(const char* a:{"fieldStudy","fieldCollect","fieldPush","fieldRepair","fieldTravel"})invalid.issueOrder(a,"bad-contact");check(snapshot(invalid.s)==before,"Field orders cannot be used from charts or cockpit");deploy(invalid);invalid.s.battery=0;auto contact=find(invalid,"mineral");before=snapshot(invalid.s);invalid.issueOrder("fieldStudy",contact.id);invalid.issueOrder("fieldPush");invalid.issueOrder("fieldRepair");check(snapshot(invalid.s)==before,"Insufficient resources and battery never consume a turn");invalid.s.battery=50;before=snapshot(invalid.s);invalid.issueOrder("fieldStudy",contact.id,true);check(snapshot(invalid.s)==before,"Paused field actions cannot advance the world");
 std::cout<<"PASS: "<<checks<<" fieldwork checks / generated sites, non-invasive study, finite collection, living biomass, real cargo, predictable movement, repairs, route interrupts, reload and rejected orders\n";return 0;
}catch(const std::exception& e){std::cerr<<"Fieldwork failure after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}}
